import{_ as s,o as e,c as n,a2 as a}from"./chunks/framework.DHDlZsL2.js";const c=JSON.parse('{"title":"06 合规交互与机械结构","description":"","frontmatter":{},"headers":[],"relativePath":"06_合规交互与机械结构.md","filePath":"06_合规交互与机械结构.md"}'),l={name:"06_合规交互与机械结构.md"};function i(o,t,r,d,g,p){return e(),n("div",null,[...t[0]||(t[0]=[a(`<h1 id="_06-合规交互与机械结构" tabindex="-1">06 合规交互与机械结构 <a class="header-anchor" href="#_06-合规交互与机械结构" aria-label="Permalink to &quot;06 合规交互与机械结构&quot;">​</a></h1><blockquote><p>本文档属于 [[00_文档指南与历年赛题/全栈技术知识库/INDEX|全栈技术知识库]]。 涵盖电赛合规地面站设计、Nextion 串口触摸屏协议封包、蓝牙多进程通信、SYN6288 语音报靶以及 06 仓 100 款 3D 打印结构件规范。</p></blockquote><hr><h2 id="_1-电赛地面站合规强制红线" tabindex="-1">1. 电赛地面站合规强制红线 <a class="header-anchor" href="#_1-电赛地面站合规强制红线" aria-label="Permalink to &quot;1. 电赛地面站合规强制红线&quot;">​</a></h2><p>全国大学生电子设计竞赛（NUEDC）对地面操作终端有着极其严厉的一票否决级要求：</p><ul><li><strong>红线条款</strong>：<strong>严禁使用通用计算机（PC 笔记本电脑、便携工控机、平板电脑及标准全尺寸键盘）</strong> 作为地面站直接参与测试；</li><li><strong>合规解法</strong>：必须自制由<strong>微控制器（单片机）驱动的便携式嵌入式手持终端</strong>，通过专用串口触摸屏（如 Nextion / 陶晶驰）、物理按键、无线透传模块（数传/蓝牙）以及语音合成芯片完成人机交互。</li></ul><hr><h2 id="_2-nextion-陶晶驰串口触摸屏交互设计与通信协议" tabindex="-1">2. Nextion / 陶晶驰串口触摸屏交互设计与通信协议 <a class="header-anchor" href="#_2-nextion-陶晶驰串口触摸屏交互设计与通信协议" aria-label="Permalink to &quot;2. Nextion / 陶晶驰串口触摸屏交互设计与通信协议&quot;">​</a></h2><p>参考源码：<code>01_锡月无人机实战系统/03_地面站/地面站主控程序.py</code> 与 <code>03_地面站/README.md</code></p><p>Nextion 智能串口屏内置图形渲染引擎，主控仅需通过 TTL 串口（波特率通常为 9600 或 115200）向屏幕发送标准 ASCII 文本控制指令。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[机载上位机 (树莓派)]</span></span>
<span class="line"><span>        │ 蓝牙无线透传 (9600bps)</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>[地面主控处理端] ──► 多进程并行处理 ──┬──► (TTL 串口 0xFF 0xFF 0xFF) ──► [Nextion 串口触摸屏]</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                                    └──► (GB2312 协议编码) ──────► [SYN6288 语音合成芯片]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_2-1-结束帧协议铁律-0xff-0xff-0xff" tabindex="-1">2.1 结束帧协议铁律（<code>0xFF 0xFF 0xFF</code>） <a class="header-anchor" href="#_2-1-结束帧协议铁律-0xff-0xff-0xff" aria-label="Permalink to &quot;2.1 结束帧协议铁律（\`0xFF 0xFF 0xFF\`）&quot;">​</a></h3><p>Nextion 屏幕的解析器以连续三个 <code>0xFF</code> 字节作为单条指令的结束判定，缺少该结束符将导致指令永远悬挂在屏幕接收缓冲区：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> send_nextion_cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ser, cmd_str):</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;&quot;&quot;向串口触摸屏发送指令的标准封包函数&quot;&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ser.write(cmd_str.encode(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;gbk&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ser.write(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytearray</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_2-2-常见控件指令集" tabindex="-1">2.2 常见控件指令集 <a class="header-anchor" href="#_2-2-常见控件指令集" aria-label="Permalink to &quot;2.2 常见控件指令集&quot;">​</a></h3><ul><li><strong>更新文本显示</strong>：<code>t0.txt=&quot;动物: 老虎&quot;</code></li><li><strong>计数器自增</strong>：<code>n0.val++</code>（统计检出的目标数量）</li><li><strong>切换页面</strong>：<code>page page1</code></li><li><strong>进度条与图形刷新</strong>：<code>j0.val=85</code></li></ul><h3 id="_2-3-多进程并发通信与-syn6288-语音报靶" tabindex="-1">2.3 多进程并发通信与 SYN6288 语音报靶 <a class="header-anchor" href="#_2-3-多进程并发通信与-syn6288-语音报靶" aria-label="Permalink to &quot;2.3 多进程并发通信与 SYN6288 语音报靶&quot;">​</a></h3><p>在 2025-H 题（野生动物巡查）中，检出动物后要求地面站即时发出语音播报。为防止串口读写阻塞导致屏幕卡死，系统采用 <code>multiprocessing</code> 架构：</p><ol><li><strong>进程 A（蓝牙接收进程）</strong>：全速监听机载树莓派通过蓝牙上传的目标分类与网格坐标，解析后放入线程安全队列 <code>Queue</code>；</li><li><strong>进程 B（交互与屏幕刷新进程）</strong>：消费队列数据，驱动 Nextion 屏幕刷新航迹与计数器；</li><li><strong>语音合成驱动</strong>：将文字按 GB2312 编码打包成帧头为 <code>0xFD</code> 的语音帧，发送给 SYN6288 芯片完成现场高保真语音播报。</li></ol><hr><h2 id="_3-3d-打印机械结构与-cad-建模规范" tabindex="-1">3. 3D 打印机械结构与 CAD 建模规范 <a class="header-anchor" href="#_3-3d-打印机械结构与-cad-建模规范" aria-label="Permalink to &quot;3. 3D 打印机械结构与 CAD 建模规范&quot;">​</a></h2><p>参考仓库：<code>drone-workspace/06_3D打印结构模型库/</code>（全仓 100 款工程规范命名模型，含 SolidWorks 原件与拓竹 3MF 切片工程）</p><p>无人机机械结构必须兼顾<strong>45cm 轴距合规包络</strong>、<strong>结构刚性</strong>与<strong>跌落抗震韧性</strong>：</p><h3 id="_3-1-核心自研结构件选型索引" tabindex="-1">3.1 核心自研结构件选型索引 <a class="header-anchor" href="#_3-1-核心自研结构件选型索引" aria-label="Permalink to &quot;3.1 核心自研结构件选型索引&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">分类</th><th style="text-align:left;">建议规范命名</th><th style="text-align:left;">对应原文件</th><th style="text-align:left;">关键工程设计要点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>四轴机架配件</strong></td><td style="text-align:left;"><strong><code>四轴一体化保护框_上盖/下盖</code></strong></td><td style="text-align:left;"><code>bhk_up3</code> / <code>bhk_down3.3mf</code></td><td style="text-align:left;">242×221mm 外廓，全包覆防护，满足赛场检录安全网硬性规定</td></tr><tr><td style="text-align:left;"><strong>机身承重中板</strong></td><td style="text-align:left;"><strong><code>大飞机机身4mm加强型主承重板</code></strong></td><td style="text-align:left;"><code>终极版1111_plate_1.stl</code></td><td style="text-align:left;">4mm 加厚碳纤级强度，吸收大机动飞行时的机身扭转形变</td></tr><tr><td style="text-align:left;"><strong>前视相机支架</strong></td><td style="text-align:left;"><strong><code>前视摄像头长臂伸出支架</code></strong></td><td style="text-align:left;"><code>da——tou.stl</code></td><td style="text-align:left;"><strong>44mm 悬臂外伸</strong>，避开前方螺旋桨遮挡视线，前视视野无死角</td></tr><tr><td style="text-align:left;"><strong>前视紧凑支架</strong></td><td style="text-align:left;"><strong><code>前视摄像头短臂紧凑支架</code></strong></td><td style="text-align:left;"><code>321312.stl</code></td><td style="text-align:left;">24mm 紧凑悬臂，重心后移，减小机头悬臂惯性力矩</td></tr><tr><td style="text-align:left;"><strong>微型传感器座</strong></td><td style="text-align:left;"><strong><code>微型传感器双孔固定转接座</code></strong></td><td style="text-align:left;"><code>123123.stl</code></td><td style="text-align:left;">27×13mm 双孔沉头固定结构，用于装载 OLED 或微型传感器</td></tr><tr><td style="text-align:left;"><strong>地面站外壳</strong></td><td style="text-align:left;"><strong><code>陶晶驰3.5寸串口屏固定背板</code></strong></td><td style="text-align:left;"><code>tao_jing_chi.stl</code></td><td style="text-align:left;">121×73.5mm，背面留有锂电池固定卡槽与手持抓握曲面</td></tr><tr><td style="text-align:left;"><strong>定高传感器座</strong></td><td style="text-align:left;"><strong><code>激光定高传感器垫高底座</code></strong></td><td style="text-align:left;"><code>ji_gaung_dian_gao_tai_mian.stl</code></td><td style="text-align:left;">30×50mm，将 ToF 模块向下探出，避开底板边缘遮挡光斑</td></tr></tbody></table><h3 id="_3-2-拓竹-3d-打印切片参数黄金建议" tabindex="-1">3.2 拓竹 3D 打印切片参数黄金建议 <a class="header-anchor" href="#_3-2-拓竹-3d-打印切片参数黄金建议" aria-label="Permalink to &quot;3.2 拓竹 3D 打印切片参数黄金建议&quot;">​</a></h3><ol><li><strong>耗材材质选型</strong>： <ul><li>结构件（机架、保护罩、底板）：首选 <strong>PETG</strong> 或 <strong>PLA-CF（碳纤维增强 PLA）</strong>，绝不能使用纯脆性 PLA（脆性高，轻微碰壁即崩裂）；</li><li>减震缓冲件（相机座、云台垫片）：使用 <strong>TPU 95A 柔性耗材</strong>，利用橡胶弹性吸收高频高振。</li></ul></li><li><strong>切片关键参数（Bambu Studio）</strong>： <ul><li><strong>壁厚圈数（Wall Loops）</strong>：设置为 <strong>4 ~ 5 层</strong>（电赛零件强度主要由外壁提供，而不是填充率）；</li><li><strong>填充率与图案</strong>：设置 <strong>25% ~ 35% 陀螺线（Gyroid）</strong> 填充，各向同性受力，兼顾极轻重量与超高抗扭强度；</li><li><strong>支撑类型</strong>：复杂悬臂使用 <strong>树状支撑（Tree Support）</strong>，接触面平整且极易徒手剥离。</li></ul></li></ol>`,27)])])}const k=s(l,[["render",i]]);export{c as __pageData,k as default};
